import React, { useState, useEffect, useRef } from "react"
import {
  Streamlit,
  withStreamlitConnection,
} from "streamlit-component-lib"
import "./FillInTheBlanks.css"

interface FillInTheBlanksProps {
  args: {
    question_text_full: string
    correctAnswer: string // This prop now holds the actual correct answer string
    default_value?: string
    disabled?: boolean
  }
}

const FillInTheBlanks: React.FC<FillInTheBlanksProps> = (props) => {
  const { question_text_full, correctAnswer, default_value, disabled } = props.args
  const [inputValue, setInputValue] = useState<string>(default_value || "")
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    if (default_value !== undefined && default_value !== inputValue) {
      setInputValue(default_value)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [default_value])

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = event.target.value
    setInputValue(newValue)
  }

  const handleBlur = () => {
    Streamlit.setComponentValue(inputValue)
  }

  // Regex to find the first sequence of 3 or more underscores
  const BLANK_PLACEHOLDER_REGEX = /_{3,}/;
  const parts = question_text_full.split(BLANK_PLACEHOLDER_REGEX);
  const beforeText = parts[0];

  // If parts.length is 1, no placeholder was found. Render the original text.
  // If parts.length > 1, a placeholder was found.
  // afterText will be the content after the first placeholder.
  // If there are multiple placeholders, this will join the text segments after the first one,
  // using the first placeholder itself as a separator, which is not what we want for rendering.
  // For a single blank, parts[1] is the text after the blank.
  // If parts[1] is undefined (e.g. question ends with ___), afterText should be empty.
  const afterText = parts.length > 1 && parts[1] !== undefined ? parts[1] : "";

  // The input field's width and maxLength will be based on the correctAnswer's length.
  const answerLength = correctAnswer ? correctAnswer.length : 0;
  // Ensure a minimum visual width (e.g., for very short answers) and a slight buffer.
  const inputWidth = `${Math.max(answerLength * 0.9, 3.0)}em`; // Approx 0.9em per char, min width ~3em
  const inputMaxLength = Math.max(1, answerLength); // Ensure maxLength is at least 1

  useEffect(() => {
    Streamlit.setFrameHeight()
  })

  // Only render the input field if a blank placeholder was found
  const showInput = parts.length > 1;

  return (
    <div className={`fill-in-the-blanks-container ${disabled ? 'disabled' : ''}`}>
      <span>{beforeText}</span>
      {showInput && (
        <input
          type="text"
          ref={inputRef}
          value={inputValue}
          onChange={handleInputChange}
          onBlur={handleBlur}
          disabled={disabled}
          style={{ width: inputWidth, minWidth: '35px' }} // Adjusted minWidth
          maxLength={inputMaxLength}
          className="blank-input"
          placeholder={disabled ? "" : "Answer..."} // Changed placeholder
        />
      )}
      {showInput && <span>{afterText}</span>} 
      {/* Fallback: If no placeholder was found, render the original question text. 
          This case should ideally be handled by frontend.py before calling the component. 
          If !showInput, it means parts.length was 1, so parts[0] is question_text_full.
          The component will render: <span>{question_text_full}</span> followed by an empty <span></span> for afterText.
      */}
      {!showInput && <span>{question_text_full}</span>}
    </div>
  )
}

export default withStreamlitConnection(FillInTheBlanks);
